:root {
  --card-bg: #1a2744;
  --card-border: #2e4080;
  --header-bg: #0f1a33;
  --accent-blue: #4a90e2;
  --accent-teal: #3ecfcf;
  --accent-warm: #f5a623;
  --text-primary: #ffffff;
  --text-secondary: #8fa8d0;
  --text-muted: #556a90;
  --stat-bg: #0f1a33;
  --stat-border: #2e4080;
  --forecast-bg: #243058;
  --forecast-active-bg: #4a90e2;
  --forecast-active-text: #ffffff;
  --dot-color: #3ecfcf;
  --divider: #2e4080;
}

.weather-card {
  background-color: var(--card-bg);
  border: 2px solid var(--card-border);
  border-radius: 20px;
  width: 500px;
  padding: 0;
  overflow: hidden;
  margin: 0 auto;
}

.card-header {
  background-color: var(--header-bg);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 20px;
  border-bottom: 1px solid var(--divider);
}

.location {
  display: flex;
  align-items: center;
  gap: 8px;
}

.location-dot {
  width: 10px;
  height: 10px;
  background-color: var(--dot-color);
  border-radius: 50%;
}

.location-name {
  color: var(--text-primary);
  font-size: 15px;
  font-weight: 600;
}

.date-label {
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.08em;
}

.main-weather {
  display: flex;
  align-items: center;
  gap: 0;
  padding: 20px 24px 16px;
  border-bottom: 1px solid var(--divider);
}

.temp-block {
  display: flex;
  align-items: flex-start;
  flex: 1;
}

.temp-value {
  font-size: 72px;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1;
}

.temp-unit {
  font-size: 28px;
  font-weight: 400;
  color: var(--accent-blue);
  margin-top: 8px;
  line-height: 1;
}

.condition-block {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 4px;
}

.condition-icon {
  font-size: 36px;
  line-height: 1;
}

.condition-text {
  color: var(--text-primary);
  font-size: 14px;
  font-weight: 600;
}

.feels-like {
  color: var(--text-secondary);
  font-size: 12px;
}

.stats-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
  padding: 14px 16px;
  border-bottom: 1px solid var(--divider);
}

.stat {
  background-color: var(--stat-bg);
  border: 1px solid var(--stat-border);
  border-radius: 10px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  padding: 10px 6px;
}

.stat-icon {
  font-size: 16px;
  line-height: 1;
}

.stat-value {
  color: var(--accent-teal);
  font-size: 13px;
  font-weight: 700;
}

.stat-label {
  color: var(--text-muted);
  font-size: 10px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.forecast-row {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 6px;
  padding: 12px 16px;
}

.forecast-item {
  background-color: var(--forecast-bg);
  border-radius: 10px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
  padding: 10px 4px;
}

.forecast-item.active {
  background-color: var(--forecast-active-bg);
}

.forecast-day {
  color: var(--text-secondary);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.forecast-item.active .forecast-day {
  color: var(--forecast-active-text);
}

.forecast-icon {
  font-size: 20px;
  line-height: 1;
}

.forecast-temp {
  color: var(--text-primary);
  font-size: 13px;
  font-weight: 600;
}
